import glob, os
import numpy as np, pandas as pd

sens = { '2025-10-14':0.020005522952956448, '2025-11-03':0.020005522952956448, '2026-03-12':0.021291541888228904 }
for b, runs in [('2025-11-03',[15,16,17,18,19,20]), ('2026-03-12',[28,29,30]), ('2025-10-14',[9,10])]:
    print('\nBATCH',b)
    for r in runs:
        f=f'data/raw/{b}/run_{r:03d}.csv'
        if b=='2026-03-12':
            d=pd.read_csv(f,sep=';'); t=d.t.values; v=d.V.values
        else:
            d=pd.read_csv(f,comment='#'); t=d.time_s.values; v=d.loadcell_V.values
        F=(v-v[t<1].mean())/sens[b]
        bins=[]
        for lo in range(0,12):
            m=(t>=lo)&(t<lo+1)
            bins.append(F[m].mean())
        print(f'run {r:2d}:', ' '.join(f'{x:6.2f}' for x in bins), ' steady(3-8)=',f'{F[(t>3)&(t<8)].mean():.3f}', 'std=',f'{F[(t>3)&(t<8)].std():.3f}')

